#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using CodeGlyphX.Benchmarks.Tools;

public sealed class CoordinateKernelSession : IDisposable {
    private readonly IsolatedCorpusSession _owner;
    private readonly MethodInfo _find;
    private readonly object _budget;
    private readonly List<object[]> _inputs = new();
    private readonly List<object> _results = new();
    public string CoreSha256 => _owner.CoreSha256;
    public string CoreInformationalVersion => _owner.CoreInformationalVersion;
    public int Count => _inputs.Count;
    public bool HasResult => _results.Count != 0;
    public CoordinateKernelSession(string root, string manifest, string imageRoot) {
        _owner = new IsolatedCorpusSession(root, manifest, imageRoot);
        try {
            var flags = BindingFlags.NonPublic | BindingFlags.Instance;
            var context = (AssemblyLoadContext)typeof(IsolatedCorpusSession).GetField("_context", flags)!.GetValue(_owner)!;
            var adapter = typeof(IsolatedCorpusSession).GetField("_session", flags)!.GetValue(_owner)!;
            var core = context.Assemblies.Single(x => x.GetName().Name == "CodeGlyphX");
            var grayType = core.GetType("CodeGlyphX.Qr.QrGrayImage", true)!;
            var pixels = (byte[][])adapter.GetType().GetField("_pixels", flags)!.GetValue(adapter)!;
            var widths = (int[])adapter.GetType().GetField("_widths", flags)!.GetValue(adapter)!;
            var heights = (int[])adapter.GetType().GetField("_heights", flags)!.GetValue(adapter)!;
            var ctor = grayType.GetConstructor(flags, null, new[] { typeof(int), typeof(int), typeof(byte[]), typeof(byte), typeof(byte), typeof(byte), typeof(byte[]) }, null)!;
            var decoder = core.GetType("CodeGlyphX.Qr.QrPixelDecoder", true)!;
            _find = decoder.GetMethod("FindComponents", BindingFlags.NonPublic | BindingFlags.Static)!;
            _budget = Activator.CreateInstance(decoder.GetNestedType("DecodeBudget", BindingFlags.NonPublic)!, new object?[] { 0, CancellationToken.None, null })!;
            for (var i = 0; i < pixels.Length; i++) {
                var gray = new byte[widths[i] * heights[i]];
                for (var at = 0; at < gray.Length; at++) {
                    var p = at * 4;
                    gray[at] = (byte)((299 * pixels[i][p] + 587 * pixels[i][p + 1] + 114 * pixels[i][p + 2] + 500) / 1000);
                }
                foreach (byte threshold in new byte[] { 96, 160 }) {
                    var image = ctor.Invoke(new object?[] { widths[i], heights[i], gray, (byte)0, (byte)255, threshold, null });
                    foreach (var invert in new[] { false, true }) _inputs.Add(new object[] { image, invert, _budget, 400, 6 });
                }
            }
        } catch { _owner.Dispose(); throw; }
    }
    public void Reset() {
        foreach (IDisposable result in _results) result.Dispose();
        _results.Clear();
    }
    public void Collect() {
        if (HasResult) throw new InvalidOperationException("Reset before the measured collection.");
        foreach (var input in _inputs) _results.Add(_find.Invoke(null, input)!);
    }
    public CoordinateKernelOutcome[] Evaluate() {
        if (_results.Count != Count) throw new InvalidOperationException("Incomplete component input coverage.");
        var output = new CoordinateKernelOutcome[Count];
        for (var i = 0; i < Count; i++) {
            var result = _results[i];
            var count = (int)result.GetType().GetProperty("Count")!.GetValue(result)!;
            var item = result.GetType().GetProperty("Item")!;
            var text = new StringBuilder();
            for (var at = 0; at < count; at++) {
                var component = item.GetValue(result, new object[] { at })!;
                foreach (var field in new[] { "MinX", "MinY", "MaxX", "MaxY", "Area" })
                    text.Append((int)component.GetType().GetProperty(field)!.GetValue(component)!).Append(',');
                text.Append(';');
            }
            output[i] = new CoordinateKernelOutcome { Variant = i, Components = count,
                DescriptorSha256 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text.ToString()))) };
        }
        return output;
    }
    public void Dispose() { Reset(); _owner.Dispose(); }
}
public sealed class CoordinateKernelOutcome {
    public int Variant { get; set; }
    public int Components { get; set; }
    public string DescriptorSha256 { get; set; } = "";
}

SpecificationSource:
$outputRoot=Get-BenchmarkInput OutputRoot
$manifest=Get-BenchmarkInput ManifestPath
$source=Get-BenchmarkInput Source
New-BenchmarkSuite 'coordinate-component-kernel' -OutputRoot $outputRoot {
    Set-BenchmarkProfile Current
    Set-BenchmarkPolicy -Warmup 3 -Iterations 12 -Order GroupedRotated -OutlierMode None
    Add-BenchmarkMetadata ManifestSha256 (Get-FileHash -LiteralPath $manifest).Hash
    Add-BenchmarkMetadata BaselineCoreSha256 $sessions.Baseline.CoreSha256
    Add-BenchmarkMetadata CandidateCoreSha256 $sessions.Candidate.CoreSha256
    Add-BenchmarkMetadata BaselineCoreInformationalVersion $sessions.Baseline.CoreInformationalVersion
    Add-BenchmarkMetadata CandidateCoreInformationalVersion $sessions.Candidate.CoreInformationalVersion
    Add-BenchmarkMetadata CandidateSource $source
    Add-BenchmarkMetadata Scope 'Actual private QR FindComponents only, unbounded budget, four preloaded images, two fixed grayscale thresholds and two polarities. Explicit identical integer luminance preparation is outside timing; these are kernel inputs, not the complete public scan pipeline. Input loading, outcome evaluation and pooled-result disposal are excluded. Every priming and measured component descriptor is retained.'
    Add-BenchmarkCases { Add-BenchmarkCase FixedComponentInputs @{} }
    Set-BenchmarkSetup {
        param($case,$run)
        $run.Session=$sessions[$case.Engine]
        if($run.Session.HasResult -and $lastIterations.ContainsKey($case.Engine) -and $lastIterations[$case.Engine] -lt 0){
            $outcomes=$run.Session.Evaluate()
            Assert-KernelOutcomes $outcomes
            $folder=Join-Path (Join-Path $run.OutputRoot $run.RunId) 'warmup-outcomes'
            [IO.Directory]::CreateDirectory($folder)|Out-Null
            [IO.File]::WriteAllText((Join-Path $folder ("{0}-{1}.json" -f $case.Engine,$lastIterations[$case.Engine])),(ConvertTo-Json -InputObject @($outcomes) -Depth 10))
        }
        $lastIterations[$case.Engine]=$run.Iteration
        $run.Session.Reset()
    }
    foreach($engineName in @('Baseline','Candidate')){
        Add-BenchmarkEngine $engineName { Add-BenchmarkOperation Collect { param($case,$run) $run.Session.Collect() } }
    }
    Add-BenchmarkValidation {
        param($case,$run)
        $run.Outcomes=$run.Session.Evaluate()
        Assert-KernelOutcomes $run.Outcomes
        [IO.File]::WriteAllText((Join-Path $run.OutputDirectory 'outcomes.json'),(ConvertTo-Json -InputObject @($run.Outcomes) -Depth 10))
    }
    Add-BenchmarkMetric Variants { param($case,$run) $run.Outcomes.Length }
    Add-BenchmarkMetric Components { param($case,$run) ($run.Outcomes|Measure-Object Components -Sum).Sum }
    Set-BenchmarkArtifacts Json, Csv, Markdown
}
